public function median(values: List of Float) returns maybe Float
  purpose: The middle value of the sorted list, or the mean of the two middle values.
  example: median([3.0, 1.0, 2.0]) is 2.0
  example: median([4.0, 1.0, 3.0, 2.0]) is 2.5
  example: median([]) is nothing

  if values.is_empty() then return nothing end

  let sorted be values.sorted()
  let length be sorted.length()

  if length.remainder(2) is 1 then
    let middle_index be length.quotient(2)
    return sorted.at(middle_index)
  otherwise
    let right_index be length.quotient(2)
    let left_index be right_index - 1
    let left be sorted.at(left_index)
    let right be sorted.at(right_index)
    return (left + right) / 2.0
  end
end
```

